import React, { useEffect, useState } from "react";

import useApi from "../../../hooks/useApi";
import { useNavigate, useParams } from "react-router-dom";
import departmentsApi from "../../../api/departmentsApi";
import { Loading } from "../../../components";
import { useStateContext } from "../../../contexts/ContextProvider";
import logisticsApi from "../../../api/logistics/logisticsApi";
import RadiologyServicesFormModal from "./RadiologyServicesFormModal";
import RadiologyServicesTable from "./RadiologyServicesTable";
import servicesApi from "../../../api/servicesApi";

const columns = [
  { name: "Title", uid: "title" },
  { name: "Description", uid: "description" },
  { name: "Date", uid: "created" },
  { name: "Actions", uid: "actions" },
];

function RadiologyServicesList() {
  const [openInventoryFormModal, setopenInventoryFormModal] = useState(false);
  const navigate = useNavigate();
  const [selectedRadiologyService, setselectedRadiologyService] = useState();
  const [radiologyServices, setradiologyServices] = useState([]);
  const [data, setdata] = useState([]);
  const [modalTitle, setmodalTitle] = useState("");
  const [updated, setUpdated] = useState(false);

  const radiologyServicesApi = useApi(servicesApi.servicesAdminAction);



  const getRadiologyServices = async (data) => {

    await radiologyServicesApi.request({
      action: "GetRadiologyServices",
     
    });
  };

  useEffect(() => {
    if (radiologyServicesApi.data) {
      if (radiologyServicesApi.data.length) {
        setradiologyServices(radiologyServicesApi.data);
      }
    }
  }, [radiologyServicesApi.data]);

  useEffect(() => {

    getRadiologyServices();


  }, []);

  useEffect(() => {
    setdata(radiologyServices);
  }, [radiologyServices]);

  const handleEditAction = (item) => {
    setopenInventoryFormModal(true);
    setselectedRadiologyService(item);
    setmodalTitle(`EDIT ${item.title}`);
    setUpdated(false)
  };

  const handleAddAction = () => {
    setopenInventoryFormModal(true);
    setmodalTitle("Add new radiology service");
    setselectedRadiologyService(null);
  };
  const handleDetailsAction = (item) => {
    navigate(`/systems/details/${item.id}`, {
      state: {
        item: item,
      },
    });
  };
  const handleDeleteAction = (item) => {
    console.log("Item", item);
    navigate(`/systems/delete/${item.id}`);
  };

  useEffect(() => {
    if (radiologyServicesApi.data && radiologyServicesApi.data.length) {
      setradiologyServices(radiologyServicesApi.data);
    }
    console.log("radiologyServicesApi.data", radiologyServicesApi.data);
  }, [radiologyServicesApi.data]);

  useEffect(() => {
    if (updated === true) {

      getRadiologyServices();
    }
  }, [updated]);

  //Filtering data
  useEffect(() => {
    setdata(radiologyServices);
  }, [radiologyServices]);

  const handleFilter = (e) => {
    const search_param = e;
    if (
      radiologyServices &&
      radiologyServices.length > 0 &&
      search_param &&
      search_param !== ""
    ) {
      setdata(
        radiologyServices.filter((x) => x.title.toLowerCase().includes(search_param))
      );
    } else {
      setdata(radiologyServices);
    }
  };

  return radiologyServicesApi.loading ? (
    <Loading loading={departmentsApi.loading} />
  ) : (
    <div className="mt-16 md:mt-2">
        {openInventoryFormModal && (
          <RadiologyServicesFormModal
            ismodalOpen={openInventoryFormModal}
            setisModalOpen={setopenInventoryFormModal}
            selectedRadiologyService={selectedRadiologyService}
            updated={updated}
            setUpdated={setUpdated}
            modalTitle={modalTitle}
          />
        )}

        <RadiologyServicesTable
          title={"Radiology Services"}
        data={data}
        columns={columns}
        editAction={handleEditAction}
        detailsAction={handleDetailsAction}
        deleteAction={handleDeleteAction}
        addAction={handleAddAction}
        handleFilter={handleFilter}
      />
    </div>
  );
}

export default RadiologyServicesList;
